Bu dərsdəki 1-ci kod nümunəsi dəqiq olaraq nə çap edir?

from dataclasses import dataclass
from typing import TypedDict

class Config(TypedDict):
    device_id: str
    enabled: bool

@dataclass(slots=True)
class Sensor:
    name: str
    value: float

def label(sensor: Sensor, unit: str | None = None) -> str:
    suffix = f' {unit}' if unit else ''
    return f'{sensor.name}: {sensor.value}{suffix}'

config: Config = {'device_id': 'sensor-1', 'enabled': True}
print(label(Sensor(config['device_id'], 21.5), 'C'))

